import{_ as n,c as o,o as i,a2 as r}from"./chunks/framework.PGES7OoM.js";const p=JSON.parse(`{"title":"Curvy for the curious","description":"","frontmatter":{"rawMarkdown":"# Curvy for the curious\\n\\nThis section explains Curvy's components and design choices in a technical manner.\\n\\nTo understand how Curvy works under the hood, we recommend first reading through the [In-depth walkthroughs](./walkthroughs/index.md).\\n\\nAs noted previously in the [Introduction](../introduction.md), Curvy's core principles are Privacy, Compliance, Utility, and Self-custody.\\n\\nThen we will explain in detail how we adhere to these principles in [Building blocks](./building-blocks/index), and define exactly what we mean by [Privacy](./privacy-model.md) and [Compliance](./compliance-model.md).\\n\\n> [!WARNING]\\n> **Privacy** and **Compliance** are words often used in spoken and written communication, where the audience and speaker almost always have wildly different definitions of the two. As this is a very careless and dangerous phenomenon, we dedicate entire sections of our docs to remove any ambiguity.\\n","rawMarkdownPath":"/_raw/for-the-curious/index.md","rawMarkdownTitle":"Curvy for the curious","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-the-curious/index.md"},"headers":[],"relativePath":"for-the-curious/index.md","filePath":"for-the-curious/index.md","lastUpdated":1773768298000}`),a={name:"for-the-curious/index.md"};function t(s,e,d,c,l,h){return i(),o("div",null,[...e[0]||(e[0]=[r("",6)])])}const m=n(a,[["render",t]]);export{p as __pageData,m as default};
